import json

path = '/home/agent/workspace/rl_contract/environment_spec.json'
issues = []

# 1. Syntactic validity
try:
    with open(path) as f:
        spec = json.load(f)
    print('JSON syntax: VALID')
except Exception as e:
    print('JSON syntax: INVALID ->', e)
    raise SystemExit(1)

# 2. State space: finite and non-empty
states = spec.get('states')
if not isinstance(states, list):
    issues.append('states is missing or not a list')
elif len(states) == 0:
    issues.append('state space is EMPTY')
else:
    print(f'State space: {len(states)} states (finite, non-empty)')

# 3. Action space: finite and non-empty
actions = spec.get('actions')
if not isinstance(actions, list):
    issues.append('actions is missing or not a list')
elif len(actions) == 0:
    issues.append('action space is EMPTY')
else:
    names = [a.get('name') for a in actions]
    print(f'Action space: {len(actions)} actions (finite, non-empty): {names}')

# 4. Cross-consistency checks
rows, cols = spec['grid']['rows'], spec['grid']['cols']
if isinstance(states, list) and len(states) != rows * cols:
    issues.append(f'states count {len(states)} != grid size {rows}x{cols}={rows*cols}')

state_set = {tuple(s) for s in states} if isinstance(states, list) else set()
start = spec.get('start_state')
if tuple(start) not in state_set:
    issues.append(f'start_state {start} not in state space')
terminals = spec.get('terminal_states', [])
for t in terminals:
    if tuple(t) not in state_set:
        issues.append(f'terminal state {t} not in state space')
if isinstance(actions, list):
    ids = [a.get('id') for a in actions]
    if len(set(ids)) != len(ids):
        issues.append('duplicate action ids')

print()
if issues:
    print('ISSUES FOUND:')
    for i in issues:
        print(' -', i)
else:
    print('ALL CHECKS PASSED: no issues found')

